package com.nextrade.engine.settlement; import com.nextrade.common.valueobject.*; import com.nextrade.domain.order.Trade; import java.math.*; public final class SettlementEngine {private final FeeSchedule fees;public SettlementEngine(FeeSchedule fees){this.fees=fees;}public SettlementInstruction prepare(Trade t,boolean taker){Money gross=new Money(t.price().value().multiply(t.quantity().value()),java.util.Currency.getInstance("INR"));Money fee=fees.fee(gross,taker);return new SettlementInstruction(t.id(),t.buyer(),t.seller(),t.instrumentId(),t.quantity(),t.price(),gross,fee);}}
